from typing import Optional, Dict, Any

from web_utils import parse_content_type, content_charset, image_type


def describe_upload(content_type: str, data: bytes) -> Dict[str, Any]:
    """
    Given a request Content-Type header value and the first bytes of the body, return:
    {
      "mime": <lower-cased media type without parameters>,
      "charset": <lower-cased charset parameter or None>,
      "image": <"png", "jpeg", "gif" or None>  # from signature bytes
    }

    Parameter values may be quoted in the header.
    """
    header = content_type or ""
    mime, _params = parse_content_type(header)  # mime is already lower-cased

    # Preserve "None" when no charset is present.
    try:
        charset = content_charset(header, default=None)
    except Exception:
        # If header parsing fails unexpectedly, fall back safely.
        charset = None
    if charset is not None:
        charset = str(charset).lower()

    detected = image_type(data)  # e.g. 'png', 'jpeg', 'gif', 'bmp', 'webp', or None
    if detected not in ("png", "jpeg", "gif"):
        detected = None

    return {"mime": mime, "charset": charset, "image": detected}

import asyncio
from typing import Any, List


def run_with_deadline(coros: list, seconds: float) -> list:
    """
    Run the given coroutines concurrently and return results in input order.

    - If a coroutine does not finish within `seconds`, it is cancelled and its result
      position is set to None.
    - Works when called repeatedly in the same process.
    """
    if seconds is None:
        raise TypeError("seconds must be a float (got None)")
    if seconds < 0:
        raise ValueError("seconds must be >= 0")

    async def _runner() -> List[Any]:
        tasks = [asyncio.create_task(c) for c in coros]
        try:
            done, pending = await asyncio.wait(tasks, timeout=seconds, return_when=asyncio.ALL_COMPLETED)
            results: List[Any] = [None] * len(tasks)

            for t in done:
                idx = tasks.index(t)  # preserves order mapping; list sizes expected small
                try:
                    results[idx] = t.result()
                except asyncio.CancelledError:
                    results[idx] = None
                except Exception:
                    # If a coroutine errors, propagate like asyncio.gather would.
                    # (Unfinished ones are not relevant once we decide to fail.)
                    raise

            if pending:
                for p in pending:
                    p.cancel()
                # Ensure cancelled tasks are fully processed.
                await asyncio.gather(*pending, return_exceptions=True)

            return results
        finally:
            # Safety: ensure no tasks are left running.
            for t in tasks:
                if not t.done():
                    t.cancel()
            if tasks:
                await asyncio.gather(*tasks, return_exceptions=True)

    # No event loop is running in the caller; create a fresh one so repeated calls work.
    loop = asyncio.new_event_loop()
    try:
        asyncio.set_event_loop(loop)
        return loop.run_until_complete(_runner())
    finally:
        try:
            loop.stop()
        finally:
            asyncio.set_event_loop(None)
            loop.close()

from __future__ import annotations

from typing import List

from shell_cmd import quote_arg


def rsync_command(sources: list[str], host: str, dest: str) -> str:
    """
    Return a single POSIX shell command line that runs:
        rsync -az <sources...> <host>:<dest>

    Each source path and the host:dest target are passed to the remote shell as
    separate, properly-quoted rsync arguments, so spaces, quotes, $, and other
    shell metacharacters are preserved.
    """
    if not isinstance(sources, list):
        raise TypeError("sources must be a list of strings")
    for s in sources:
        if not isinstance(s, str):
            raise TypeError("each source must be a string")

    if not isinstance(host, str):
        raise TypeError("host must be a string")
    if not isinstance(dest, str):
        raise TypeError("dest must be a string")

    target = f"{host}:{dest}"
    args: List[str] = ["rsync", "-az", *sources, target]
    return " ".join(quote_arg(a) for a in args)
